"use client";

import { useId, useState } from "react";
import { Lightbulb, Plus, RotateCcw } from "lucide-react";
import { cn } from "@/lib/utils";
import { panel, secondary } from "@/lib/takt-surface";

const hints = [
  "Compare the lengths of UI-7 and UI-42.",
  "Check how many digits [0-9] accepts.",
  "In [a-z]+ the plus allows consecutive letters.",
];
export function HintLadder({
  items = hints,
  onReveal,
  className,
}: {
  items?: string[];
  onReveal?: (index: number) => void;
  className?: string;
}) {
  const [count, setCount] = useState(0);
  const id = useId();
  const shown = Math.min(count, items.length);
  return (
    <section className={cn(panel, "grid w-72 max-w-full gap-3", className)}>
      <header className="flex items-center gap-2">
        <Lightbulb size={16} />
        <strong>Hints</strong>
        <output className="ml-auto font-mono text-xs">
          {shown} / {items.length}
        </output>
      </header>
      <div aria-hidden className="flex gap-1">
        {items.map((_, i) => (
          <i
            key={i}
            className={cn(
              "h-1 flex-1 rounded-full motion-safe:transition-colors",
              i < shown ? "bg-primary" : "bg-muted",
            )}
          />
        ))}
      </div>
      <ol id={id} aria-live="polite" className="grid gap-2 empty:hidden">
        {items.slice(0, shown).map((hint, i) => (
          <li
            key={i}
            className="flex items-baseline gap-3 text-xs leading-relaxed motion-safe:animate-in motion-safe:fade-in motion-safe:slide-in-from-bottom-2"
          >
            <span className="font-mono text-muted-foreground">
              {String(i + 1).padStart(2, "0")}
            </span>
            {hint}
          </li>
        ))}
      </ol>
      {shown < items.length ? (
        <button
          type="button"
          aria-controls={id}
          className={secondary}
          onClick={() => {
            setCount(shown + 1);
            onReveal?.(shown);
          }}
        >
          <Plus size={14} />
          {shown ? "Next hint" : "Reveal hint"}
        </button>
      ) : (
        shown > 0 && (
          <button
            type="button"
            className={secondary}
            onClick={() => setCount(0)}
          >
            <RotateCcw size={13} />
            Hide hints
          </button>
        )
      )}
    </section>
  );
}

// Semantic shadcn colors keep the surfaces usable in a host project's own theme.
export const panel =
  "rounded-2xl border border-foreground/10 bg-card p-4 text-sm text-card-foreground shadow-[0_2px_5px_#0000000a,0_8px_18px_-12px_#0003]";
export const field =
  "min-h-10 min-w-0 w-full rounded-xl border border-foreground/10 bg-muted/70 px-3 text-sm text-foreground outline-none motion-safe:transition-[background-color,box-shadow] focus:bg-background focus:ring-1 focus:ring-foreground/35";
export const action =
  "inline-flex min-h-10 cursor-pointer items-center justify-center gap-2 rounded-xl border border-foreground/10 bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground shadow-sm outline-offset-4 motion-safe:transition-[transform,box-shadow] motion-safe:active:translate-y-px motion-safe:active:scale-[.97] disabled:cursor-default disabled:opacity-50";
export const secondary =
  "inline-flex min-h-9 cursor-pointer items-center justify-center gap-1.5 rounded-lg border border-foreground/10 bg-background px-3 text-xs font-medium text-foreground outline-offset-2 hover:bg-muted motion-safe:transition-[transform,background-color] motion-safe:active:scale-[.96] disabled:cursor-default disabled:opacity-45";
